/**
 * کشِ کوتاه‌عمرِ درون‌حافظه‌ای برای خواندن‌هایی که برای *همه* یکی‌اند.
 *
 * =============================================================================
 * چرا لازم شد
 * =============================================================================
 *
 * محتوای بازی‌ها، بانکِ سؤالِ آزمون، فهرستِ آزمون‌ها، اعلانِ سایت و آمارِ کلاب
 * برای هر بازدیدکننده دقیقاً یکی‌اند، ولی تا امروز *هر* بازدید دوباره از
 * دیتابیس خوانده می‌شدند. با پنجاه کاربرِ هم‌زمان یعنی پنجاه کوئریِ یکسان در
 * یک لحظه — و روی هاستِ اشتراکی، سقفِ اتصالِ دیتابیس زودتر از هر چیزِ دیگری
 * پر می‌شود.
 *
 * این ماژول دو کار می‌کند:
 *
 *   ۱) TTL: نتیجه تا `ttlMs` در حافظه می‌ماند.
 *   ۲) single-flight: اگر کش خالی است و صد درخواست هم‌زمان برسند، فقط *یکی*
 *      به دیتابیس می‌رود و بقیه منتظرِ همان Promise می‌مانند. بدون این،
 *      لحظهٔ انقضای کش خودش یک «هجوم» می‌ساخت (thundering herd).
 *
 * =============================================================================
 * آنچه باید دانست
 * =============================================================================
 *
 * ⚠️ فقط برای داده‌ای که به کاربر وابسته نیست. کلید هیچ‌وقت شناسهٔ کاربر
 * ندارد و نباید داشته باشد؛ دادهٔ شخصی جایش اینجا نیست.
 *
 * ⚠️ کش مالِ *همین پروسه* است. Passenger روی cPanel ممکن است چند پروسه
 * بالا بیاورد؛ `invalidate()` فقط پروسه‌ای را پاک می‌کند که ذخیرهٔ مدیر را
 * انجام داده. بقیه حداکثر تا پایانِ TTL دادهٔ قبلی را نشان می‌دهند. به همین
 * دلیل TTL ها کوتاه‌اند (ثانیه‌ها تا یک دقیقه) و نه ساعت.
 *
 * ⚠️ خطا کش نمی‌شود. اگر بارگذاری شکست بخورد، درخواستِ بعدی دوباره تلاش
 * می‌کند — دیتابیسی که یک لحظه در دسترس نبود نباید یک دقیقه «خالی» بماند.
 *
 * ⚠️ اندازه سقف دارد. بعضی کلیدها از نشانی می‌آیند (مثلاً کلیدِ آزمون)، و
 * بدونِ سقف یک خزنده می‌توانست با نشانی‌های ساختگی حافظه را پر کند.
 */

type Entry = { value: unknown; expiresAt: number };

const MAX_ENTRIES = 500;

const store = new Map<string, Entry>();
const inflight = new Map<string, Promise<unknown>>();

/**
 * مقدارِ `key`، از کش یا با یک بار صدا زدنِ `load`.
 *
 * `keep` اختیاری است و می‌گوید کدام نتیجه ارزشِ نگه داشتن دارد. برای کلیدی که
 * از نشانی می‌آید، «پیدا نشد» نباید کش شود: وگرنه هر نشانیِ ساختگی یک خانه از
 * سقفِ کش را می‌گرفت و ورودی‌های واقعی را بیرون می‌راند.
 */
export function memo<T>(
  key: string,
  ttlMs: number,
  load: () => Promise<T>,
  keep: (value: T) => boolean = () => true,
): Promise<T> {
  const hit = store.get(key);
  if (hit && hit.expiresAt > Date.now()) return Promise.resolve(hit.value as T);

  const pending = inflight.get(key);
  if (pending) return pending as Promise<T>;

  const promise = Promise.resolve()
    .then(load)
    .then(
      (value) => {
        /* ⚠️ فقط اگر در این فاصله `invalidate` صدا نزده باشد. بارگذاری‌ای که
           *پیش* از ذخیرهٔ مدیر شروع شده، دادهٔ کهنه را دارد و نباید تا یک دقیقه
           جای دادهٔ تازه بنشیند. */
        if (inflight.get(key) === promise) {
          inflight.delete(key);
          if (keep(value)) {
            if (store.size >= MAX_ENTRIES && !store.has(key)) {
              // قدیمی‌ترین ورودی (Map ترتیبِ درج را نگه می‌دارد).
              const oldest = store.keys().next().value;
              if (oldest !== undefined) store.delete(oldest);
            }
            store.set(key, { value, expiresAt: Date.now() + ttlMs });
          }
        }
        return value;
      },
      (err: unknown) => {
        if (inflight.get(key) === promise) inflight.delete(key);
        throw err;
      },
    );

  inflight.set(key, promise);
  return promise;
}

/**
 * همهٔ کلیدهایی که با `prefix` شروع می‌شوند را پاک می‌کند.
 *
 * بارگذاری‌های در جریان هم از فهرست بیرون می‌روند تا نتیجه‌شان — که پیش از
 * تغییر خوانده شده — در کش ننشیند. بی‌پیشوند، همه‌چیز پاک می‌شود.
 */
export function invalidate(prefix = ""): void {
  for (const key of [...store.keys()]) if (key.startsWith(prefix)) store.delete(key);
  for (const key of [...inflight.keys()]) if (key.startsWith(prefix)) inflight.delete(key);
}
